<?php
// Favorites page: list only recipes saved by the signed-in member.
require_once __DIR__.'/helpers.php';require_login();$q=$pdo->prepare('SELECT r.*,c.name category,u.name author,(SELECT COUNT(*) FROM comments cm WHERE cm.recipe_id=r.id) comment_count,(SELECT COUNT(*) FROM favorites f WHERE f.recipe_id=r.id) favorite_count FROM favorites mine JOIN recipes r ON r.id=mine.recipe_id JOIN categories c ON c.id=r.category_id JOIN users u ON u.id=r.user_id WHERE mine.user_id=? ORDER BY mine.created_at DESC');$q->execute([(int)$_SESSION['user']['id']]);$recipes=$q->fetchAll();$pageTitle='My favorites';require __DIR__.'/header.php';?>
<section class="discover favorites-page"><div class="section-heading"><div><p class="eyebrow">YOUR PERSONAL RECIPE BOX</p><h1>Saved with love <span>♥</span></h1><p class="muted">The dishes you want to come back to.</p></div><span class="result-count"><?= count($recipes) ?> saved</span></div><?php if($recipes): ?><div class="recipe-grid"><?php foreach($recipes as $i=>$r): ?><article class="recipe-card"><a class="card-image image-<?= $i%4 ?>" href="recipe.php?id=<?= (int)$r['id'] ?>"><span class="category-pill"><?= h($r['category']) ?></span><span class="dish-illustration" aria-hidden="true"><?= ['🍛','🥘','🍜','🍮'][$i%4] ?></span><span class="image-caption">LUTONG BAHAY</span></a><div class="card-body"><div class="card-meta"><span><?= (int)$r['cook_minutes'] ?> MIN <b>·</b> <?= (int)$r['servings'] ?> SERVINGS</span><span>♡ <?= (int)$r['favorite_count'] ?></span></div><h3><a href="recipe.php?id=<?= (int)$r['id'] ?>"><?= h($r['title']) ?></a></h3><p><?= h($r['description']) ?></p><div class="card-bottom"><span>by <b><?= h($r['author']) ?></b></span><span><?= (int)$r['comment_count'] ?> comments</span><button class="favorite-button is-favorite" type="button" data-favorite="<?= (int)$r['id'] ?>" aria-pressed="true" title="Remove favorite">♥</button></div></div></article><?php endforeach; ?></div><?php else: ?><div class="empty-state"><span>♡</span><h3>Your recipe box is waiting.</h3><p>Tap the heart on any recipe to save it for later.</p><a class="button button-dark" href="index.php">Explore recipes</a></div><?php endif; ?></section>
<?php require __DIR__.'/footer.php';?>
